import {AppStoreServerAPIClient,Environment} from '@apple/app-store-server-library';
import {loadAppleReviewSecret} from './dist/apple-production-secret.js';
import {createRilloraAppleReviewVerifier} from './dist/apple-production-verification.js';
console.log(JSON.stringify({probe:'apple-test-signature',phase:'start',time:new Date().toISOString()}));
try {
const c=await loadAppleReviewSecret(process.env.APPLE_REVIEW_SECRET_ARN);
const api=new AppStoreServerAPIClient(c.privateKey,c.keyId,c.issuerId,c.bundleId,Environment.SANDBOX);
const status=await api.getTestNotificationStatus("56ef9595-2978-4314-b894-9b0f0e5e730e_1790838486521");
const verifier=await createRilloraAppleReviewVerifier('/app/certificates/apple');
const payload=await verifier.verifyAndDecodeNotification(status.signedPayload);
console.log(JSON.stringify({probe:'apple-test-signature',verified:true,type:payload.notificationType,environment:payload.data?.environment,bundleId:payload.data?.bundleId}));
} catch(e) {console.log(JSON.stringify({probe:'apple-test-signature',verified:false,status:e.status??null,name:e.name,causeName:e.cause?.name??null,causeType:e.cause?.type??null,causeCode:e.cause?.code??null,message:e.message}));process.exitCode=2;}
